//! OptiScaler Community Compatibility & AMD FSR Redstone Knowledge Graph.
//! Includes 700 OptiScaler tested games and 400+ AMD FSR Redstone (FSR 4) titles.

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum OptiStatus {
    Working,
    Partial,
    NotWorking,
}

impl OptiStatus {
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::Working => "Working",
            Self::Partial => "Partial / Caveats",
            Self::NotWorking => "Incompatible / Anti-Cheat",
        }
    }
}

#[derive(Debug, Clone)]
pub struct OptiCompatEntry {
    pub name: &'static str,
    pub norm_name: &'static str,
    pub status: OptiStatus,
    pub inputs: &'static str,
    pub optipatcher: bool,
    pub notes: &'static str,
    pub recommended_hook: Option<&'static str>,
    pub auto_exposure: bool,
    pub non_linear_color_space: bool,
    pub disable_spoofing: bool,
    pub fsr2_pattern: bool,
    pub force_dx12_param: bool,
}

#[derive(Debug, Clone)]
pub struct FsrRedstoneEntry {
    pub title: &'static str,
    pub norm_title: &'static str,
    pub has_native_fg: bool,
}

#[derive(Debug, Clone, Default)]
pub struct CompatibilityProfile {
    pub opti_status: Option<OptiStatus>,
    pub opti_inputs: Option<String>,
    pub optipatcher_supported: bool,
    pub opti_notes: Option<String>,
    pub recommended_hook: Option<&'static str>,
    pub auto_exposure: bool,
    pub non_linear_color_space: bool,
    pub disable_spoofing: bool,
    pub fsr2_pattern: bool,
    pub force_dx12_param: bool,
    pub fsr_redstone_supported: bool,
    pub fsr_redstone_native_fg: bool,
    pub rx7000_redstone_upscaling: bool,
}

pub fn normalize_title(title: &str) -> String {
    title.chars().filter(|c| c.is_alphanumeric()).flat_map(|c| c.to_lowercase()).collect()
}

