use std::sync::RwLock;

static DYNAMIC_ENTRIES: RwLock<Vec<crate::updater::CachedCompatEntry>> = RwLock::new(Vec::new());

/// Loads dynamic compatibility entries into runtime memory (e.g. from local cache or online sync).
pub fn load_dynamic_entries(entries: &[crate::updater::CachedCompatEntry]) {
    if let Ok(mut dyn_entries) = DYNAMIC_ENTRIES.write() {
        *dyn_entries = entries.to_vec();
    }
}

/// Look up an OptiScaler community compatibility entry by title.
pub fn lookup_optiscaler(title: &str) -> Option<&'static OptiCompatEntry> {
    let norm = normalize_title(title);
    if norm.is_empty() {
        return None;
    }
    // Exact normalized match
    if let Some(entry) = OPTISCALER_COMPAT_DB.iter().find(|e| e.norm_name == norm) {
        return Some(entry);
    }
    // Substring match
    OPTISCALER_COMPAT_DB.iter().find(|e| {
        !e.norm_name.is_empty() && (norm.contains(e.norm_name) || e.norm_name.contains(&norm))
    })
}

/// Look up an AMD FSR "Redstone" (FSR 4) entry by title.
pub fn lookup_redstone(title: &str) -> Option<&'static FsrRedstoneEntry> {
    let norm = normalize_title(title);
    if norm.is_empty() {
        return None;
    }
    // Exact normalized match
    if let Some(entry) = FSR_REDSTONE_DB.iter().find(|e| e.norm_title == norm) {
        return Some(entry);
    }
    // Substring match
    FSR_REDSTONE_DB.iter().find(|e| {
        !e.norm_title.is_empty() && (norm.contains(e.norm_title) || e.norm_title.contains(&norm))
    })
}

/// Generate a full compatibility profile combining OptiScaler & AMD FSR Redstone.
pub fn lookup_compatibility(title: &str) -> CompatibilityProfile {
    let norm = normalize_title(title);

    // 1. Check live/cached dynamic entries first
    if let Ok(guard) = DYNAMIC_ENTRIES.read() {
        if !guard.is_empty() {
            if let Some(entry) = guard.iter().find(|e| {
                e.norm_name == norm
                    || (!e.norm_name.is_empty() && (norm.contains(&e.norm_name) || e.norm_name.contains(&norm)))
            }) {
                let status = match entry.status.as_str() {
                    "Working" => OptiStatus::Working,
                    "NotWorking" => OptiStatus::NotWorking,
                    _ => OptiStatus::Partial,
                };
                let mut profile = CompatibilityProfile::default();
                profile.opti_status = Some(status);
                profile.opti_inputs = Some(entry.inputs.clone());
                profile.optipatcher_supported = entry.optipatcher;
                if !entry.notes.is_empty() {
                    profile.opti_notes = Some(entry.notes.clone());
                }
                profile.recommended_hook = match entry.recommended_hook.as_deref() {
                    Some("winmm.dll") => Some("winmm.dll"),
                    Some("d3d12.dll") => Some("d3d12.dll"),
                    Some("version.dll") => Some("version.dll"),
                    _ => None,
                };
                profile.auto_exposure = entry.auto_exposure;
                profile.non_linear_color_space = entry.non_linear_color_space;
                profile.disable_spoofing = entry.disable_spoofing;
                profile.fsr2_pattern = entry.fsr2_pattern;
                profile.force_dx12_param = entry.force_dx12_param;

                if let Some(r) = lookup_redstone(title) {
                    profile.fsr_redstone_supported = true;
                    profile.fsr_redstone_native_fg = r.has_native_fg;
                    profile.rx7000_redstone_upscaling = true;
                }

                return profile;
            }
        }
    }

    // 2. Fall back to embedded static database
    let opti = lookup_optiscaler(title);
    let redstone = lookup_redstone(title);

    let mut profile = CompatibilityProfile::default();

    if let Some(entry) = opti {
        profile.opti_status = Some(entry.status);
        profile.opti_inputs = Some(entry.inputs.to_string());
        profile.optipatcher_supported = entry.optipatcher;
        if !entry.notes.is_empty() {
            profile.opti_notes = Some(entry.notes.to_string());
        }
        profile.recommended_hook = entry.recommended_hook;
        profile.auto_exposure = entry.auto_exposure;
        profile.non_linear_color_space = entry.non_linear_color_space;
        profile.disable_spoofing = entry.disable_spoofing;
        profile.fsr2_pattern = entry.fsr2_pattern;
        profile.force_dx12_param = entry.force_dx12_param;
    }

    if let Some(r) = redstone {
        profile.fsr_redstone_supported = true;
        profile.fsr_redstone_native_fg = r.has_native_fg;
        profile.rx7000_redstone_upscaling = true;
    }

    profile
}

